        state.edgeHitboxes = [];
        const C = state.cartan;
        const useQuiverArrows = state.quiverMode && supportsQuiverOrientation(state.type);
        const quiverOrientations = useQuiverArrows ? getQuiverOrientations(state.type, state.rank, C) : null;
